solution.code:
function App() {
  const [showName, setShowName] = useState(true);
  const [name, setName] = useState('Ada');
  const [count, setCount] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setShowName(v => !v)}>Toggle name</button>
      {showName && <p>Name: {name}</p>}
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
    </div>
  );
}

function App() {
  const [active, setActive] = useState(false);
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!active) return; // condition inside, not around
    const id = setInterval(() => setN(v => v + 1), 1000);
    return () => clearInterval(id);
  }, [active]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setActive(a => !a)}>{active ? 'Stop' : 'Start'}</button>
      <p>n = {n}</p>
    </div>
  );
}
